import { useEffect, useState } from "react";
import api from "../api";

export default function AdminDashboard() {
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [votingOpen, setVotingOpen] = useState(false);
  const [newCandidate, setNewCandidate] = useState({ name: "", position: "", party: "" });

  // Fetch pending users and candidates on mount
  useEffect(() => {
    fetchPendingUsers();
    fetchCandidates();
    fetchVotingStatus();
  }, []);

  // ---------------------- FETCH FUNCTIONS ----------------------
  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/candidates");
      setCandidates(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchVotingStatus = async () => {
    try {
      const res = await api.get("/admin/voting-status");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      console.error(err);
    }
  };

  // ---------------------- ACTION FUNCTIONS ----------------------
  const approveUser = async (userId) => {
    try {
      await api.post(`/admin/approve-user/${userId}`);
      alert("User approved ✅");
      fetchPendingUsers();
    } catch (err) {
      alert(err.response?.data?.error || "Failed to approve user ❌");
    }
  };

  const rejectUser = async (userId) => {
    try {
      await api.post(`/admin/reject-user/${userId}`);
      alert("User rejected ❌");
      fetchPendingUsers();
    } catch (err) {
      alert(err.response?.data?.error || "Failed to reject user ❌");
    }
  };

  const toggleVoting = async () => {
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
      alert(`Voting is now ${res.data.votingOpen ? "OPEN" : "CLOSED"}`);
    } catch (err) {
      alert(err.response?.data?.error || "Failed to toggle voting ❌");
    }
  };

  const addCandidate = async () => {
    try {
      await api.post("/candidates", newCandidate);
      alert("Candidate added ✅");
      setNewCandidate({ name: "", position: "", party: "" });
      fetchCandidates();
    } catch (err) {
      alert(err.response?.data?.error || "Failed to add candidate ❌");
    }
  };

  const deleteCandidate = async (id) => {
    try {
      await api.delete(`/candidates/${id}`);
      alert("Candidate deleted ❌");
      fetchCandidates();
    } catch (err) {
      alert(err.response?.data?.error || "Failed to delete candidate ❌");
    }
  };

  // ---------------------- RENDER ----------------------
  return (
    <div className="min-h-screen p-8 bg-gray-100">
      <h1 className="text-3xl font-bold mb-6">Admin Dashboard</h1>

      {/* Voting Control */}
      <section className="mb-8">
        <h2 className="text-xl font-semibold mb-2">Voting Period</h2>
        <button
          onClick={toggleVoting}
          className={`px-4 py-2 rounded text-white ${votingOpen ? "bg-red-600" : "bg-green-600"}`}
        >
          {votingOpen ? "Close Voting" : "Open Voting"}
        </button>
      </section>

      {/* Pending Users */}
      <section className="mb-8">
        <h2 className="text-xl font-semibold mb-2">Pending User Approvals</h2>
        {pendingUsers.length === 0 ? (
          <p>No pending users.</p>
        ) : (
          <ul>
            {pendingUsers.map((user) => (
              <li key={user.id} className="flex justify-between items-center mb-2">
                <span>{user.name} ({user.studentNumber})</span>
                <div>
                  <button
                    onClick={() => approveUser(user.id)}
                    className="bg-green-600 text-white px-3 py-1 rounded mr-2"
                  >
                    Approve
                  </button>
                  <button
                    onClick={() => rejectUser(user.id)}
                    className="bg-red-600 text-white px-3 py-1 rounded"
                  >
                    Reject
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>

      {/* Candidates */}
      <section className="mb-8">
        <h2 className="text-xl font-semibold mb-2">Candidates</h2>
        <div className="mb-4 flex gap-2">
          <input
            type="text"
            placeholder="Name"
            value={newCandidate.name}
            onChange={(e) => setNewCandidate({ ...newCandidate, name: e.target.value })}
            className="px-2 py-1 border rounded"
          />
          <input
            type="text"
            placeholder="Position"
            value={newCandidate.position}
            onChange={(e) => setNewCandidate({ ...newCandidate, position: e.target.value })}
            className="px-2 py-1 border rounded"
          />
          <input
            type="text"
            placeholder="Party (optional)"
            value={newCandidate.party}
            onChange={(e) => setNewCandidate({ ...newCandidate, party: e.target.value })}
            className="px-2 py-1 border rounded"
          />
          <button
            onClick={addCandidate}
            className="bg-blue-600 text-white px-4 py-1 rounded"
          >
            Add
          </button>
        </div>

        {candidates.length === 0 ? (
          <p>No candidates yet.</p>
        ) : (
          <ul>
            {candidates.map((c) => (
              <li key={c.id} className="flex justify-between items-center mb-2">
                <span>{c.name} - {c.position} {c.party && `(${c.party})`}</span>
                <button
                  onClick={() => deleteCandidate(c.id)}
                  className="bg-red-600 text-white px-3 py-1 rounded"
                >
                  Delete
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>

      {/* Reports */}
      <section className="mb-8">
        <h2 className="text-xl font-semibold mb-2">Reports</h2>
        <button
          onClick={() => alert("Generate report API call here")}
          className="bg-gray-700 text-white px-4 py-2 rounded"
        >
          Generate Final Report
        </button>
      </section>
    </div>
  );
}
